import{_ as e,o as n,c as i,j as a,a as o,aa as r}from"./chunks/framework.BAs_AphD.js";const d="/buildary-help-preview/academy/img/zalozeni-domeny/05.webp",l="/buildary-help-preview/media/cs/diary/uzivateledomeny.png",g=JSON.parse('{"title":"Firemní doména","description":"","frontmatter":{"title":"Firemní doména","wiki":"cs:firstofall:domain"},"headers":[],"relativePath":"firstofall/domain.md","filePath":"firstofall/domain.md","lastUpdated":1795418046000}'),s={name:"firstofall/domain.md"};function m(u,t,v,p,c,k){return n(),i("div",null,[...t[0]||(t[0]=[a("h1",{id:"firemni-domena",tabindex:"-1"},[o("Firemní doména "),a("a",{class:"header-anchor",href:"#firemni-domena","aria-label":'Permalink to "Firemní doména"'},"​")],-1),a("p",null,[a("strong",null,"Doména"),o(" zastřešuje stavby jedné firmy: jejich uživatele, společná nastavení, logo a fakturaci. Každý uživatel má od prvního přihlášení svou "),a("strong",null,"osobní doménu"),o(". Pokud v Buildary pracujete jako firma s vlastními stavbami a lidmi, založte si "),a("strong",null,"firemní doménu"),o(".")],-1),a("p",null,[o("Krok za krokem: "),a("a",{href:"/buildary-help-preview/akademie/domena"},"Založit firemní doménu"),o(" v Akademii.")],-1),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/EpqdNLNExLo",title:"Video: Doména",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),r('<h2 id="potrebuji-firemni-domenu" tabindex="-1">Potřebuji firemní doménu? <a class="header-anchor" href="#potrebuji-firemni-domenu" aria-label="Permalink to &quot;Potřebuji firemní doménu?&quot;">​</a></h2><ul><li><strong>Ano</strong>, pokud firma zakládá vlastní stavby a přidává na ně své zaměstnance.</li><li><strong>Ne</strong>, pokud pracujete jen na stavbách, kam vás někdo přizval, nebo máte jednu vlastní stavbu (třeba rodinný dům). Osobní doména vám stačí.</li></ul><p>Doménu může založit kdokoli; kdo ji založí, stává se jejím vlastníkem. Osobní doménu si nechte na zkoušení a pro firmu založte samostatnou.</p><h2 id="zalozit-domenu" tabindex="-1">Založit doménu <a class="header-anchor" href="#zalozit-domenu" aria-label="Permalink to &quot;Založit doménu&quot;">​</a></h2><p>V levém panelu klikněte na ikonu glóbu – otevře se <strong>Seznam domén</strong>. Na prvním řádku je vždy vaše osobní doména. Novou založíte tlačítkem <strong>Nová doména</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Formulář Nová doména" loading="lazy"></figure><p>Ve formuláři vyplníte:</p><ul><li><strong>Název domény</strong> – obvykle název firmy.</li><li><strong>Role</strong> – zda je firma zpravidla <strong>Stavebník</strong>, nebo <strong>Zhotovitel</strong>. Je to jen výchozí hodnota, na každé stavbě ji můžete změnit.</li><li><strong>Výchozí nastavení modulů pro nové stavby</strong> – moduly, které se na nových stavbách zapnou samy.</li><li><strong>Logo</strong> (nejvýše 120 × 100 px) – zobrazí se v aplikaci a jako logo vlevo v každém nově založeném deníku a v jeho PDF. Logo je na tmavém pozadí, proto se hodí bílé nebo hodně světlé.</li><li><strong>Firma</strong> a <strong>adresa</strong> – údaje načtete podle IČO tlačítkem <strong>ARES</strong> (u slovenských firem <strong>Slovensko Digital</strong>).</li><li><strong>Kontakt pro fakturaci</strong> – e-mail, na který budou chodit výzvy k platbě a faktury. Můžete uvést i více adres.</li></ul><div class="warning custom-block"><p class="custom-block-title">Plátci DPH</p><p>Pokud je firma plátce DPH, vyplňte <strong>DIČ DPH</strong> – jinak doménu nepůjde uložit.</p></div><h2 id="spravovat-domenu" tabindex="-1">Spravovat doménu <a class="header-anchor" href="#spravovat-domenu" aria-label="Permalink to &quot;Spravovat doménu&quot;">​</a></h2><p>Doménu otevřete v Seznamu domén ikonou tužky. V <strong>detailu domény</strong> jsou záložky:</p><table tabindex="0"><thead><tr><th>Záložka</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Správa domény</strong></td><td>Upravit údaje o doméně nebo aktualizovat údaje firmy.</td></tr><tr><td><strong>Uživatelé domény</strong></td><td>Přidat uživatele tlačítkem <strong>Přidat</strong>, upravit je ikonou tužky a přidělit jim práva.</td></tr><tr><td><strong>Přehledy uživatelů</strong></td><td>Export do XLS: uživatelé po stavbách, počet licencí, seznam staveb. Tady také nahradíte jednoho uživatele jiným.</td></tr><tr><td><strong>Fakturace za doménu</strong></td><td>Všechny výzvy k platbě a daňové doklady za provoz a archivaci – viz <a href="/buildary-help-preview/firstofall/payment">Placený režim a fakturace</a>.</td></tr><tr><td><strong>Nastavení docházky</strong></td><td>Napojit docházkové systémy, ze kterých deníky načítají osoby na staveništi – viz <a href="/buildary-help-preview/diary/attendance_system">Docházkový systém</a>.</td></tr></tbody></table><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="Záložka Uživatelé domény" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title">Kdo patří do domény</p><p>Do domény přidávejte jen lidi z vaší firmy. Lidi z jiných firem (stavebník, podzhotovitelé, technický dozor) zvete až na konkrétní stavbu do <a href="/buildary-help-preview/diary/projectteam">projektového týmu</a> – součástí vaší domény nebudou.</p></div><p>Jaká práva mají uživatelé domény a jak se liší od práv na stavbě a v deníku, popisuje stránka <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p>',15)])])}const y=e(s,[["render",m]]);export{g as __pageData,y as default};
